const GREEN_MARKER='/* @motion-code:green-screen */';

/**
 * Replaces the first conventional full-canvas background paint generated by
 * Motion Studio. If none exists, it inserts a green paint at the script entry.
 * The marker makes repeated clicks idempotent; project history provides undo.
 */
export function addGreenScreenBackground(code:string):{code:string;replaced:boolean}{
  if(code.includes(GREEN_MARKER))return{code,replaced:false};
  const background=/(ctx\.fillStyle\s*=\s*[^;]+;\s*ctx\.fillRect\(\s*0\s*,\s*0\s*,\s*(?:W|width)\s*,\s*(?:H|height)\s*\)\s*;?)/;
  const green=`${GREEN_MARKER}\n  ctx.fillStyle = "#00ff00";\n  ctx.fillRect(0, 0, typeof W === "number" ? W : width, typeof H === "number" ? H : height);`;
  if(background.test(code))return{code:code.replace(background,green),replaced:true};
  const functionStart=/(export\s+)?function\s+renderFrame\s*\([^)]*\)\s*\{/;
  if(functionStart.test(code))return{code:code.replace(functionStart,m=>`${m}\n  ${green}`),replaced:false};
  return{code:`${green}\n${code}`,replaced:false};
}

export function hasGreenScreenBackground(code:string):boolean{return code.includes(GREEN_MARKER)}
